import json, re, datetime
try:
    vars['route']='service_error'
    b=vars.get('balance') or {}
    if isinstance(b,str): b=json.loads(b)
    months=['','Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']
    units=['sıfır','bir','iki','üç','dört','beş','altı','yedi','sekiz','dokuz']
    tens=['','on','yirmi','otuz','kırk','elli','altmış','yetmiş','seksen','doksan']
    def number(n):
        n=int(n)
        if n<10: return units[n]
        if n<100: return tens[n//10]+(' '+units[n%10] if n%10 else '')
        if n<1000: return ('' if n//100==1 else units[n//100]+' ')+'yüz'+(' '+number(n%100) if n%100 else '')
        for scale,label in [(1000000000000,'trilyon'),(1000000000,'milyar'),(1000000,'milyon'),(1000,'bin')]:
            if n>=scale: return ('' if scale==1000 and n//scale==1 else number(n//scale)+' ')+label+(' '+number(n%scale) if n%scale else '')
        return ''
    names={'TL':'Türk Lirası','USD':'Dolar','EUR':'Euro','GBP':'İngiliz Sterlini'}
    def decimal_text(v):
        s=str(v).lower()
        if 'e' not in s: return s
        mantissa,exponent=s.split('e')
        exponent=int(exponent)
        sign='-' if mantissa.startswith('-') else ''
        mantissa=mantissa.lstrip('+-')
        parts=mantissa.split('.')
        ds=''.join(parts)
        point=len(parts[0])+exponent
        if point<=0: return sign+'0.'+'0'*(-point)+ds
        if point>=len(ds): return sign+ds+'0'*(point-len(ds))
        return sign+ds[:point]+'.'+ds[point:]
    def amount(v,c):
        s=decimal_text(v)
        if s.startswith('-'): return 'borcunuz bulunmamaktadır'
        parts=s.split('.')
        whole=int(parts[0])
        tail=parts[1].rstrip('0') if len(parts)>1 else ''
        if len(tail)>2: return number(whole)+' '+names[c]+' virgül '+' '.join(units[int(x)] for x in tail)
        fraction=int(tail.ljust(2,'0')) if tail else 0
        return number(whole)+' '+names[c]+(' '+number(fraction)+(' kuruş' if c=='TL' else (' peni' if c=='GBP' else ' sent')) if fraction else '')
    def date(s):
        x=datetime.datetime.strptime(s,'%d.%m.%Y').date()
        return str(x.day)+' '+months[x.month]+' '+str(x.year)
    def safe(s):
        s=str(s or '').strip()
        low=s.lower().replace('ı','i').replace('ş','s')
        return s if s and len(s)<=100 and not re.search(r'(?:\d[\s.-]*){5,}|ignore|instruction|system|prompt|talimat|kurallar|sifre|password|pin|sms|https?://|[<>\n\r{}]',low) else ''
    last=str(vars.get('selected_last4') or '')
    if not re.fullmatch(r'[0-9]{4}',last): raise ValueError('invalid label')
    product=safe(vars.get('selected_name'))
    intro='Sonu '+' '.join(units[int(x)] for x in last)+' ile biten '+(product+' ' if product else '')+'kartınız'
    today=datetime.datetime.fromisoformat(str(vars.get('now')).replace('Z','+00:00')).astimezone(datetime.timezone(datetime.timedelta(hours=3))).date()
    issued=datetime.datetime.strptime(b['statementDate'],'%d.%m.%Y').date() if b.get('statementDate') else None
    due=datetime.datetime.strptime(b['lastPayDate'],'%d.%m.%Y').date() if b.get('lastPayDate') else None
    next_cut=datetime.datetime.strptime(b['nextStatementDate'],'%d.%m.%Y').date() if b.get('nextStatementDate') else None
    future=bool(issued and issued>today)
    cut_day=today==issued or today==next_cut
    overdue=bool(due and today>due)
    mode='total' if cut_day or overdue else 'statement'
    no_debt=b.get('statementPaymentStatus')=='NO_DEBT' and mode=='statement'
    lines=[]
    clear=[]
    if not issued:
        lines.append(intro+'ın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.')
        if b.get('nextStatementDate'): lines.append('İlk hesap kesim tarihiniz '+date(b['nextStatementDate'])+' olacak.')
        no_debt=True
    elif no_debt:
        lines.append(intro+'ın '+date(b['statementDate'])+(' tarihli ekstre bilgilerine göre borcunuz bulunmamaktadır.' if future else ' tarihli ekstresinden borcunuz bulunmamaktadır.'))
        tl=b.get('debtTL') or {}
        if tl and tl['totalDebt']>=0: lines.append('Gelecek dönemler dahil toplam borcunuz '+amount(tl['totalDebt'],'TL')+'.')
        if due: lines.append('Son ödeme tarihiniz bugündür.' if due==today else 'Son ödeme tarihiniz '+date(b['lastPayDate'])+' olacaktır.')
    else:
        if cut_day: lines.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
        elif overdue: lines.append('Son ödeme tarihiniz geçmiştir.')
        transferred=[names[c] for c in ['USD','EUR','GBP'] if b.get('debt'+c) and b['debt'+c]['transferAmount']>0]
        if transferred: lines.append('Türk Lirası borcunuza aktarılan para birimi: '+', '.join(transferred)+'.')
        if mode=='statement': prefix=intro+'ınıza ait '+date(b['statementDate'])+(' tarihli ekstre bilgilerinde ' if future else ' tarihinde kesilen ekstre ')
        else: prefix=intro+' için '
        for c in ['TL','USD','EUR','GBP']:
            d=b.get('debt'+c)
            if not d: continue
            debt=d['remainingDebt'] if mode=='statement' else d['totalDebt']
            if debt<=0: clear.append(names[c]); continue
            if mode=='total': sentence=names[c]+' toplam borcunuz '+amount(d['totalDebt'],c)+'.'
            elif c!='TL': sentence=names[c]+' borcunuz '+amount(d['statementDebt'],c)+', kalan toplam borcunuz '+amount(d['remainingDebt'],c)+', ödenmesi gereken minimum tutar '+amount(d['minPayment'],c)+'.'
            elif d['remainingMinPayment']<=0: sentence='Türk Lirası borcunuz '+amount(d['statementDebt'],c)+', kalan toplam borcunuz '+amount(d['remainingDebt'],c)+'. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
            elif d['remainingMinPayment']>=d['minPayment']: sentence='Türk Lirası borcunuz '+amount(d['statementDebt'],c)+', ödenmesi gereken minimum tutar '+amount(d['minPayment'],c)+'.'
            else: sentence='Türk Lirası borcunuz '+amount(d['statementDebt'],c)+', ödenmesi gereken minimum tutar '+amount(d['minPayment'],c)+', kalan toplam borcunuz '+amount(d['remainingDebt'],c)+', kalan minimum ödeme tutarınız '+amount(d['remainingMinPayment'],c)+'.'
            lines.append(prefix+sentence)
            prefix=''
        if prefix: lines.append(intro+' için mevcut para birimlerinde borcunuz bulunmamaktadır.')
        if clear: lines.append((', '.join(clear[:-1])+' ve '+clear[-1] if len(clear)>1 else clear[0])+' borcunuz bulunmamaktadır.')
        auto=(b.get('debtTL') or {}).get('remainAutomaticPaymentAmount',0)
        if overdue and b.get('automaticPaymentFlag')=='Y' and auto>0: lines.append('Otomatik ödemenizden alınacak kalan tutar '+amount(auto,'TL')+'.')
        if due and not cut_day: lines.append('Borçlarınız için son ödeme tarihiniz bugündür.' if due==today else 'Borçlarınız için son ödeme tarihiniz '+date(b['lastPayDate'])+'.')
    figure=str(vars.get('requested_figure') or '')
    if figure=='due': lines=[intro+' için son ödeme tarihiniz bugündür.' if due==today else intro+' için son ödeme tarihiniz '+date(b['lastPayDate'])+'.'] if due else [intro+' için kesilmiş bir ekstreye ait son ödeme tarihi bulunmuyor.']
    elif figure=='minimum':
        lines=[intro+' için '+names[c]+' minimum ödeme tutarı '+amount(d['minPayment'],c)+'.' for c in ['TL','USD','EUR','GBP'] for d in [b.get('debt'+c)] if d and d['remainingDebt']>0]
        if not lines: lines=[intro+' için ekstre borcunuz bulunmamaktadır.']
    vars['requested_figure']=''
    vars['no_debt_branch']='yes' if no_debt else ''
    seen=vars.get('seen_cards') or []
    if isinstance(seen,str): seen=json.loads(seen)
    if vars.get('selected_card') not in seen: seen.append(vars.get('selected_card'))
    vars['seen_cards']=seen
    cards=vars.get('cards') or []
    if isinstance(cards,str): cards=json.loads(cards)
    others=any(c.get('isMainCard') is True and c.get('cardNumber') not in seen for c in cards)
    direct=vars.get('pending_email')=='yes' or vars.get('pending_week')=='yes'
    ask_other=others and not figure and not direct
    vars['stage']='another' if ask_other else 'reading'
    vars['question']='Başka bir kartınızın borcunu öğrenmek ister misiniz?' if ask_other else 'Başka bir isteğiniz var mı?'
    vars['speech']=' '.join(lines)+(' '+vars['question'] if ask_other else '')
    vars['tries']=0
    vars['route']='listen' if ask_other else ('contact_reading' if direct or figure or not no_debt else 'menu_reading')
except Exception:
    vars['route']='service_error'
    vars['speech']='Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'

