def _service_value(raw, path):
    import json
    value = raw
    for part in path.split('.') if path else []:
        if isinstance(value, str):
            try:
                value = json.loads(value)
            except Exception:
                return None
        if not isinstance(value, dict) or part not in value:
            return None
        value = value[part]
    return value

def _service_has_path(raw, path):
    import json
    value = raw
    for part in path.split('.') if path else []:
        if isinstance(value, str):
            try:
                value = json.loads(value)
            except Exception:
                return False
        if not isinstance(value, dict) or part not in value:
            return False
        value = value[part]
    return True

